                text: "// No ErrorBoundary anywhere, which is what an app looks like until someone\n// adds one. Every card reads its fields straight off the item, so the card\n// holding null throws while the list is being rebuilt. The fix is an\n// <ErrorBoundary> wrapped around every part of the tree that has to keep\n// working on its own, written by hand at each boundary.\n\nconst CRASH_CARDS = []\nfor( let i = 1; i <= 20; ++i ) {\n\tCRASH_CARDS.push( { id: i, title: 'Card ' + i, text: 'Details for card ' + i } )\n}\n\nfunction CrashCard( props ) {\n\treturn html`\n\t\t<div class=\"card\">\n\t\t\t<div class=\"card_title\">${ () => props.item.title }</div>\n\t\t\t<div class=\"card_text\">${ () => props.item.text }</div>\n\t\t</div>\n\t`\n}\n\nlet crash_control = null\n\nfunction CrashApp() {\n\n\tconst [ items, set_items ] = createSignal( CRASH_CARDS )\n\n\t// Handle for the runner, which swaps the data from outside the view.\n\tcrash_control = { set_items: set_items }\n\n\treturn html`\n\t\t<div class=\"cards\" data-role=\"cards\">\n\t\t\t<${ For } each=${ items }>${ item => html`\n\t\t\t\t<${ CrashCard } item=${ item } />\n\t\t\t` }<//>\n\t\t</div>\n\t`\n}\n\nconst crash = {\n\n\tmount: container => render( CrashApp, container ),\n\n\trun: async () => {\n\n\t\tconst control = crash_control\n\t\tif( !control ) throw new Error( 'Crash scenario is not mounted' )\n\n\t\tconst broken = CRASH_CARDS.slice()\n\t\tbroken[ 6 ] = null\n\n\t\tmuted = true\n\t\ttry {\n\t\t\tcontrol.set_items( broken )\n\t\t} catch( error ) {\n\t\t\t// The render error travels back out to whoever wrote the signal.\n\t\t}\n\n\t\tawait delay( 200 )\n\t\tmuted = false\n\n\t\tconst cards = document.querySelectorAll( '.card' ).length\n\t\t// Nothing renders this marker here — there is no error placeholder\n\t\t// without an ErrorBoundary. The check stays so all runners score the\n\t\t// same way.\n\t\tconst placeholder = !!document.querySelector( '[data-role=\"card-error\"]' )\n\t\t// Card 7 is the one whose data went null, so its old title still\n\t\t// being on screen is how the run tells that the list was never\n\t\t// updated at all — a third outcome next to a dead tree and a hole.\n\t\tconst seventh = document.querySelectorAll( '.card' )[ 6 ]\n\t\tconst stale = !!seventh && seventh.textContent.indexOf( 'Card 7' ) === 0\n\n\t\treturn {\n\t\t\tstatus: cards === 0 ? 'fail' : cards === 19 && placeholder ? 'ok' : 'warn',\n\t\t\tobserved: cards === 0\n\t\t\t\t? 'Card 7 threw during render, 0 of 20 cards remained'\n\t\t\t\t: stale\n\t\t\t\t\t? 'Card 7 threw during render, the list kept the previous ' + cards + ' cards'\n\t\t\t\t\t: cards + ' of 20 cards survived, card 7 '\n\t\t\t\t\t\t+ ( placeholder ? 'was replaced by an error placeholder' : 'disappeared without a placeholder' ),\n\t\t\tmetrics: [ { name: 'Surviving cards', value: cards, unit: '' } ],\n\t\t}\n\t},\n}",
