                text: "// Idiomatic data loading: an effect reads the selected id, starts a request\n// and writes whatever comes back into a signal. There is no cancellation and\n// no check that the id it started with is still the selected one, so a slow\n// earlier response still lands after a fast later one. The usual fixes are a\n// stale flag released from the effect's onCleanup, an AbortController, or\n// `resource()`, which does the cancelling for you — each of them written in\n// by hand, and each of them absent until someone notices they are needed.\n\nconst RACE_USERS = [ 1, 2, 3, 4, 5 ].map( number => ( {\n\tid: number,\n\tname: 'User ' + number,\n\tabout: 'Profile details for user ' + number + '.',\n} ) )\n\nfunction fetch_user( id ) {\n\treturn new Promise( done => {\n\t\tsetTimeout( () => done( RACE_USERS[ id - 1 ] ), 1000 - ( id - 1 ) * 200 )\n\t} )\n}\n\nconst RaceApp = Component( {\n\tselector: 'versus-app',\n\ttemplate: `\n\t\t<div class=\"row2\">\n\t\t\t<div class=\"side\">\n\t\t\t\t@for ( item of users; track item.id ) {\n\t\t\t\t\t<button\n\t\t\t\t\t\tclass=\"item\"\n\t\t\t\t\t\t[class.item_current]=\"item.id === id()\"\n\t\t\t\t\t\t[attr.data-user]=\"item.id\"\n\t\t\t\t\t\t(click)=\"id.set( item.id )\"\n\t\t\t\t\t>{{ item.name }}</button>\n\t\t\t\t}\n\t\t\t</div>\n\t\t\t<div class=\"main\">\n\t\t\t\t@if ( loading() ) {\n\t\t\t\t\t<div class=\"muted\">Loading…</div>\n\t\t\t\t} @else if ( user() ) {\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<div class=\"title\" data-panel=\"name\">{{ user().name }}</div>\n\t\t\t\t\t\t<div class=\"muted\">{{ user().about }}</div>\n\t\t\t\t\t</div>\n\t\t\t\t} @else {\n\t\t\t\t\t<div class=\"muted\">Pick a user</div>\n\t\t\t\t}\n\t\t\t</div>\n\t\t</div>\n\t`,\n} )( class {\n\n\tusers = RACE_USERS\n\tid = signal( null )\n\tuser = signal( null )\n\tloading = signal( false )\n\n\tconstructor() {\n\t\tview = this\n\t\teffect( () => {\n\t\t\tconst id = this.id()\n\t\t\tif( id === null ) return\n\t\t\tthis.loading.set( true )\n\t\t\tfetch_user( id ).then( data => {\n\t\t\t\tthis.user.set( data )\n\t\t\t\tthis.loading.set( false )\n\t\t\t} )\n\t\t} )\n\t}\n} )\n\nconst race = {\n\n\tcomponent: RaceApp,\n\n\trun: async () => {\n\n\t\tconst started = performance.now()\n\n\t\tclick( '[data-user=\"1\"]' )\n\t\tawait delay( 100 )\n\t\tclick( '[data-user=\"5\"]' )\n\t\tawait delay( 1500 )\n\n\t\t// Clamped timers collapse both responses into one wake-up and destroy\n\t\t// the order the scenario is built on. Expected here is ~1600 ms.\n\t\tif( performance.now() - started > 2200 ) throw new Invalid( 'timers-throttled' )\n\n\t\tconst panel = document.querySelector( '[data-panel=\"name\"]' )\n\t\tconst shown = panel ? panel.textContent : ''\n\t\tconst number = shown.replace( /\\D+/g, '' )\n\n\t\treturn {\n\t\t\tstatus: number === '5' ? 'ok' : 'fail',\n\t\t\tobserved: number\n\t\t\t\t? 'Selected user 5, panel shows user ' + number\n\t\t\t\t: 'Selected user 5, panel shows nothing',\n\t\t\tmetrics: [],\n\t\t}\n\t},\n}\n\n\n// ------------------------------------------------------------- virtual",
