                file: "assets/versus/solid/runner.html",
                text: "// Data loading as the Solid docs teach it: createResource takes the selected\n// id as its source and re-runs the fetcher whenever that id changes. There is\n// no cancellation flag and no AbortController here — the request itself is\n// never cut short, and aborting it for real still means wiring an\n// AbortController through onCleanup by hand. What the resource does do\n// without being asked is keep only the request it started last, so an answer\n// that arrives for an id nobody is looking at any more is dropped instead of\n// being written into the panel.\n\nconst RACE_USERS = [ 1, 2, 3, 4, 5 ].map( number => ( {\n\tid: number,\n\tname: 'User ' + number,\n\tabout: 'Profile details for user ' + number + '.',\n} ) )\n\nfunction fetch_user( id ) {\n\treturn new Promise( done => {\n\t\tsetTimeout( () => done( RACE_USERS[ id - 1 ] ), 1000 - ( id - 1 ) * 200 )\n\t} )\n}\n\nfunction RaceApp() {\n\n\tconst [ id, set_id ] = createSignal( null )\n\tconst [ user ] = createResource( id, fetch_user )\n\n\treturn html`\n\t\t<div class=\"row2\">\n\t\t\t<div class=\"side\">\n\t\t\t\t<${ For } each=${ RACE_USERS }>${ item => html`\n\t\t\t\t\t<button\n\t\t\t\t\t\tclass=${ () => 'item' + ( item.id === id() ? ' item_current' : '' ) }\n\t\t\t\t\t\tdata-user=${ item.id }\n\t\t\t\t\t\tonClick=${ () => set_id( item.id ) }\n\t\t\t\t\t>${ item.name }</button>\n\t\t\t\t` }<//>\n\t\t\t</div>\n\t\t\t<div class=\"main\">\n\t\t\t\t<${ Show }\n\t\t\t\t\twhen=${ () => !user.loading }\n\t\t\t\t\tfallback=${ () => html`<div class=\"muted\">Loading…</div>` }\n\t\t\t\t>\n\t\t\t\t\t<${ Show }\n\t\t\t\t\t\twhen=${ () => user() }\n\t\t\t\t\t\tfallback=${ () => html`<div class=\"muted\">Pick a user</div>` }\n\t\t\t\t\t>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div class=\"title\" data-panel=\"name\">${ () => user().name }</div>\n\t\t\t\t\t\t\t<div class=\"muted\">${ () => user().about }</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t<//>\n\t\t\t\t<//>\n\t\t\t</div>\n\t\t</div>\n\t`\n}\n\nconst race = {\n\n\tmount: container => render( RaceApp, container ),\n\n\trun: async () => {\n\n\t\tconst started = performance.now()\n\n\t\tclick( '[data-user=\"1\"]' )\n\t\tawait delay( 100 )\n\t\tclick( '[data-user=\"5\"]' )\n\t\tawait delay( 1500 )\n\n\t\t// Clamped timers collapse both responses into one wake-up and destroy\n\t\t// the order the scenario is built on. Expected here is ~1600 ms.\n\t\tif( performance.now() - started > 2200 ) throw new Invalid( 'timers-throttled' )\n\n\t\tconst panel = document.querySelector( '[data-panel=\"name\"]' )\n\t\tconst shown = panel ? panel.textContent : ''\n\t\tconst number = shown.replace( /\\D+/g, '' )\n\n\t\treturn {\n\t\t\tstatus: number === '5' ? 'ok' : 'fail',\n\t\t\tobserved: number\n\t\t\t\t? 'Selected user 5, panel shows user ' + number\n\t\t\t\t: 'Selected user 5, panel shows nothing',\n\t\t\tmetrics: [],\n\t\t}\n\t},\n}\n\n\n// ------------------------------------------------------------- virtual",
